import * as React from "react";

type ListItem = {
  item: string;
};

type TextBlock = {
  title: string;
  text: string;
};

type ListBlock = {
  title: string;
  items: ListItem[];
};

export type ExtractiveServiceSummaryContent = {
  definition: TextBlock;
  whenItApplies: ListBlock;
  measurement: ListBlock;
  commonMistakes: ListBlock;
};

type ExtractiveServiceSummaryProps = {
  content?: ExtractiveServiceSummaryContent | null;
};

const cardClassName =
  "rounded-2xl border border-black/10 bg-primary/70 p-5 shadow-sm supports-[backdrop-filter]:bg-purplesemilight/40 supports-[backdrop-filter]:backdrop-blur text-light";

function hasListItems(items?: ListItem[]) {
  return Array.isArray(items) && items.some((item) => item?.item);
}

const ExtractiveServiceSummary: React.FC<ExtractiveServiceSummaryProps> = ({
  content,
}) => {
  if (
    !content?.definition?.title ||
    !content.definition.text ||
    !content.whenItApplies?.title ||
    !content.measurement?.title ||
    !content.commonMistakes?.title
  ) {
    return null;
  }

  return (
    <section className="py-10 sm:py-14">
      <div className="mx-auto w-full max-w-6xl px-4 sm:px-6">
        <div className={`${cardClassName} mx-auto max-w-4xl`}>
          <h2 className="text-xl sm:text-2xl font-semibold text-light/90">
            {content.definition.title}
          </h2>
          <p className="mt-3 text-sm sm:text-base text-light/75 leading-relaxed">
            {content.definition.text}
          </p>
        </div>

        <div className="mt-6 grid grid-cols-1 gap-4 md:grid-cols-3">
          <div className={cardClassName}>
            <h3 className="text-base sm:text-lg font-semibold text-light/90">
              {content.whenItApplies.title}
            </h3>
            {hasListItems(content.whenItApplies.items) ? (
              <ul className="mt-4 list-disc pl-5 space-y-2 text-sm sm:text-base text-light/80">
                {content.whenItApplies.items.map((item, index) => (
                  <li key={`${item.item}-${index}`}>{item.item}</li>
                ))}
              </ul>
            ) : null}
          </div>

          <div className={cardClassName}>
            <h3 className="text-base sm:text-lg font-semibold text-light/90">
              {content.measurement.title}
            </h3>
            {hasListItems(content.measurement.items) ? (
              <ul className="mt-4 list-disc pl-5 space-y-2 text-sm sm:text-base text-light/80">
                {content.measurement.items.map((item, index) => (
                  <li key={`${item.item}-${index}`}>{item.item}</li>
                ))}
              </ul>
            ) : null}
          </div>

          <div className={cardClassName}>
            <h3 className="text-base sm:text-lg font-semibold text-light/90">
              {content.commonMistakes.title}
            </h3>
            {hasListItems(content.commonMistakes.items) ? (
              <ul className="mt-4 list-disc pl-5 space-y-2 text-sm sm:text-base text-light/80">
                {content.commonMistakes.items.map((item, index) => (
                  <li key={`${item.item}-${index}`}>{item.item}</li>
                ))}
              </ul>
            ) : null}
          </div>
        </div>
      </div>
    </section>
  );
};

export default ExtractiveServiceSummary;
